// Bounces the ball off the brick it just hit: flips the hit axis (both on a
// corner) and pushes the ball back out of the rectangle.
export function bounceOffBrick(ball, brick, hit) {
  const cx = ball.x - (brick.x + brick.w / 2);
  const cy = ball.y - (brick.y + brick.h / 2);
  if (hit.axis === 'x') {
    ball.vx = -ball.vx;
    ball.x = cx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (hit.axis === 'y') {
    ball.vy = -ball.vy;
    ball.y = cy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = cx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = cy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}
```

