// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (swept detection: the ball is tested
// along its whole displacement, so a fast ball can never jump an obstacle).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept: the ball bounces when its bottom edge crosses the paddle's
  // band [paddle.y, paddle.y + paddle.h] during the step, so a fast ball can
  // never jump over the paddle (the discrete band test missed it at speed).
  if (
    ball.vy > 0 &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    const bottom = ball.y + ball.r;
    const prevBottom = bottom - ball.vy * dt;
    if (prevBottom <= paddle.y + paddle.h && bottom >= paddle.y) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Bricks — swept detection, one bounce per pass. The earliest contact
  // decides the face; every brick hit at the same instant dies, but the ball
  // is deflected exactly once (a per-brick flip would cancel itself on a
  // grid seam and let the ball through).
  let earliest = Infinity;
  let hitBrick = null;
  let hitDesc = null;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, prev, brick);
    if (!hit) continue;
    hits.push({ brick, hit });
    if (hit.t < earliest) {
      earliest = hit.t;
      hitBrick = brick;
      hitDesc = hit;
    }
  }

  if (hitBrick) {
    bounceOffBrick(ball, prev, hitBrick, hitDesc);
    for (const { brick, hit } of hits) {
      if (brick === hitBrick) continue;
      if (Math.abs(hit.t - hitDesc.t) < EPS) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }
    hitBrick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(hitBrick, state.combo);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

