// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. Kept as a tested primitive; the game itself uses the
// swept test below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision (swept, pure) ----------------------------------------

// Numerical tolerance for face/corner comparisons: a difference below it
// counts as "equal" for floating-point purposes.
const EPS = 1e-9;

// Per-axis entry/exit times of the ball's box sweeping along `d` against the
// brick's range [b0, b1]. Returns [entry, exit] — the times, in steps, during
// which the two overlap on that axis (t = 0 is the frame start, t = 1 the
// frame end) — or null when they never overlap (parallel and disjoint).
function axisSweep(c0, r, d, b0, b1) {
  if (d === 0) {
    return c0 - r < b1 && c0 + r > b0 ? [-Infinity, Infinity] : null;
  }
  if (d > 0) {
    return [(b0 - (c0 + r)) / d, (b1 - (c0 - r)) / d];
  }
  return [(b1 - (c0 - r)) / d, (b0 - (c0 + r)) / d];
}

// Swept test of the ball (a circle, box-approximated) against one brick over
// the step that took it from `prev` to its current position. Continuous
// detection: a fast ball can never jump over a brick without touching it.
// Returns { t, axis } — the time of first contact in [0, 1] and the face hit
// ('x' | 'y' | 'corner') — or null when the ball never touches the brick.
export function sweptBrickHit(ball, prev, brick) {
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;
  const sx = axisSweep(prev.x, ball.r, dx, brick.x, brick.x + brick.w);
  const sy = axisSweep(prev.y, ball.r, dy, brick.y, brick.y + brick.h);
  if (!sx || !sy) return null;
  const tFirst = Math.max(sx[0], sy[0]);
  const tLast = Math.min(sx[1], sy[1]);
  if (!(tFirst < tLast) || tLast < 0 || tFirst > 1) return null;
  const t = Math.max(0, tFirst);
  let axis;
  if (t === 0) {
    // Already overlapping at frame start: the smallest penetration decides
    // the face; equal penetrations mean a corner (both axes flip).
    const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    axis = Math.abs(penX - penY) < EPS ? 'corner' : penX < penY ? 'x' : 'y';
  } else {
    // Crossing during the step: the axis entered last is the face hit.
    axis = Math.abs(sx[0] - sy[0]) < EPS ? 'corner' : sx[0] > sy[0] ? 'x' : 'y';
  }
  return { t, axis };
}

// Bounces the ball off the brick it just hit: flips the hit axis (both on a
// corner) and pushes the ball back out of the rectangle, edge against face.
export function bounceOffBrick(ball, prev, brick, hit) {
  // Contact point along the swept path: the side of the brick the ball came
  // from is read there, not at the post-move position (a fast ball may have
  // crossed the brick entirely by the end of the step).
  const contact =
    hit.t > 0
      ? {
          x: prev.x + (ball.x - prev.x) * hit.t,
          y: prev.y + (ball.y - prev.y) * hit.t,
        }
      : { x: ball.x, y: ball.y };
  const fromLeft = contact.x < brick.x + brick.w / 2;
  const fromTop = contact.y < brick.y + brick.h / 2;

  if (hit.axis === 'x') {
    ball.vx = -ball.vx;
    ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (hit.axis === 'y') {
    ball.vy = -ball.vy;
    ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

edits.oldText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

edits.newText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks. Brick collisions are swept (the ball
// is tested along its whole displacement): a fast ball can never jump an
// obstacle, and a grid seam never bounces twice.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept: the ball bounces when its bottom edge crosses the band
  // [paddle.y, paddle.y + paddle.h] during the step, so a fast ball can never
  // jump over the paddle (the discrete band test missed it at speed).
  if (ball.vy > 0 && ball.x >= paddle.x && ball.x <= paddle.x + paddle.w) {
    const bottom = ball.y + ball.r;
    const prevBottom = bottom - ball.vy * dt;
    if (prevBottom <= paddle.y + paddle.h && bottom >= paddle.y) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Bricks — swept detection, one bounce per pass. The earliest contact
  // decides the face; every brick hit at the same instant dies, but the ball
  // is deflected exactly once (a per-brick flip would cancel itself on a
  // grid seam and let the ball through).
  let earliest = Infinity;
  let hitBrick = null;
  let hitDesc = null;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, prev, brick);
    if (!hit) continue;
    hits.push({ brick, hit });
    if (hit.t < earliest) {
      earliest = hit.t;
      hitBrick = brick;
      hitDesc = hit;
    }
  }

  if (hitBrick) {
    bounceOffBrick(ball, prev, hitBrick, hitDesc);
    for (const { brick, hit } of hits) {
      if (brick === hitBrick) continue;
      if (Math.abs(hit.t - hitDesc.t) < EPS) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }
    hitBrick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(hitBrick, state.combo);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

